service.method:

DELETE FROM
	#DB_OWNER#SFFDT
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND FORM_ID = ${FORM_ID}
AND BLOCK_NAME = ${BLOCK_NAME}


		INSERT INTO #DB_OWNER#SFFDT
		(
			  HOUSE_CODE
			, FORM_ID
			, BLOCK_NAME
			, REQUIRED
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
			, CHANGE_USER_ID
			, CHANGE_DATE
			, CHANGE_TIME
            , INPUT_WIDTH
            , BLOCK_TYPE
		)
		VALUES
		(
			  ${HOUSE_CODE}
			, ${FORM_ID}
			, ${BLOCK_NAME}
			, ${REQUIRED}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
            , ${INPUT_WIDTH}
            , ${ITEM_TYPE}
		)


DELETE FROM
	SLANG
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND SCREEN_ID = ${FORM_ID}
AND "LANGUAGE" = ${session.LANGUAGE}
AND CODE = ${BLOCK_NAME}


INSERT INTO SLANG
(
	  HOUSE_CODE
	, SCREEN_ID
	, "LANGUAGE"
	, CODE
	, CONTENTS
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  ${HOUSE_CODE}
	, ${FORM_ID}
	, ${session.LANGUAGE}
	, ${BLOCK_NAME}
	, ${LABEL}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)


UPDATE
	SLANG
SET
	  CONTENTS = ${LABEL}
	, CHANGE_USER_ID = ${session.ID}
	, CHANGE_DATE = ${current.DATE}
	, CHANGE_TIME = ${current.TIME}
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND SCREEN_ID = ${FORM_ID}
AND "LANGUAGE" = ${session.LANGUAGE}
AND CODE = ${BLOCK_NAME}
